CELLS = [
"import numpy as np\nimport torch\nfrom torch.nn import functional as F\n\ndef step_rewards(sk, rs, smean, alpha=2.0):\n    \"\"\"NLG step reward (pre = smoothed prior accuracy on the skill BEFORE this attempt,\n    post = mean of the next <=2 attempts on the same skill) and the old r_gain = y_next - y_now.\"\"\"\n    sk = np.asarray(sk).tolist(); rs = np.asarray(rs, dtype=np.float64).tolist()\n    n = len(sk)\n    nxt = [-1] * n; last = {}\n    for i in range(n - 1, -1, -1):\n        k = sk[i]; nxt[i] = last.get(k, -1); last[k] = i\n    rn = np.zeros(n, np.float32); mn = np.zeros(n, np.float32)\n    rg = np.zeros(n, np.float32); mg = np.zeros(n, np.float32)\n    Sd, Cd = {}, {}\n    for i in range(n):\n        k = sk[i]; s = Sd.get(k, 0.0); c = Cd.get(k, 0)\n        j = nxt[i]\n        if j >= 0:\n            pre = (s + alpha * smean[k]) / (c + alpha)\n            j2 = nxt[j]\n            post = rs[j] if j2 < 0 else 0.5 * (rs[j] + rs[j2])\n            v = (post - pre) / max(1 - pre, 1e-3) if post >= pre else (post - pre) / max(pre, 1e-3)\n            rn[i] = max(-1.0, min(1.0, v)); mn[i] = 1.0\n            rg[i] = rs[j] - rs[i]; mg[i] = 1.0\n        Sd[k] = s + rs[i]; Cd[k] = c + 1\n    return rn, mn, rg, mg",
"sk = [0, 1, 0, 0, 1, 2, 0]\nrs = [0, 0, 1, 1, 0, 1, 1]\nsmean = [0.5, 0.7, 0.4]\nrn, mn, rg, mg = step_rewards(sk, rs, smean)\nprint('NLG 收益 rn：', rn)\nprint('有没有定义 mn：', mn)\nprint('r_gain rg：', rg)",
"torch.manual_seed(0)\nB, T, K = 2, 5, 3\nTEMP, WCLIP, C_TARGET = 0.05, 20.0, 0.7\nlam, gamma, eps, beta = 1.0, 10.0, 0.005, 0.1\np = torch.tensor([[[0.9, 0.6, 0.3]] * T, [[0.5, 0.75, 0.2]] * T])   # KT 主干预测的各知识点答对概率\ng = torch.zeros(B, T, K, requires_grad=True)                     # 策略头 g 的输出，初始为 0\na = torch.tensor([[0, 1, 1, 2, 0], [1, 1, 0, 1, 2]])               # 日志里实际出的知识点\nmu = torch.full((B, T), 1 / 3)                                   # 旧策略选它的概率\nr = torch.tensor([[0.0, 0.4, 0.3, -0.1, 0.0], [0.5, 0.2, -0.2, 0.3, 0.0]])   # NLG 收益\nQ = torch.tensor([0.0, 0.3, 0.1])                                # 每个知识点的平均收益\nbce, bce_base = torch.tensor(0.56), torch.tensor(0.55)\n\nscore = -(p - C_TARGET) ** 2 / TEMP + g\npi = torch.softmax(score, -1)\ndm = (pi * Q.view(1, 1, -1)).sum(-1)\npia = pi.gather(-1, a.unsqueeze(-1)).squeeze(-1)\nw = (pia / mu).clamp(max=WCLIP)\nqa = Q[a]\nV = dm + w * (r - qa)\nloss = bce - lam * V.mean() + beta * V.var() + gamma * F.relu(bce - (1 + eps) * bce_base)\nloss.backward()\nprint('π（第 1 个学生）：', pi[0, 0])\nprint('V_DR =', round(V.mean().item(), 4), '  loss =', round(loss.item(), 4))\nprint('g 的梯度（第 1 个学生、第 2 步）：', g.grad[0, 1])",
]
